test('@checkout @e2e @smoke @test_type:regression Complete purchase flow', async ({ page }) => {
  let shouldContinue = true;

  // Step 1: Navigate to inventory
  if (shouldContinue) {
    try {
      await page.click('[data-test="continue-shopping"]');
      await inventoryPage.assertOnInventoryPage();
    } catch (error) {
      shouldContinue = false;
    }
  }

  // Step 2: Add second item
  if (shouldContinue) {
    try {
      await inventoryPage.addProductToCart('sauce-labs-bike-light');
    } catch (error) {
      shouldContinue = false;
    }
  }

  // Step 3: Go to checkout
  if (shouldContinue) {
    try {
      await inventoryPage.goToCart();
      await page.click('[data-test="checkout"]');
    } catch (error) {
      shouldContinue = false;
    }
  }

  // Step 4: Fill form
  if (shouldContinue) {
    try {
      await checkoutPage.fillCheckoutForm('Jane', 'Smith', '54321');
      await checkoutPage.continueCheckout();
    } catch (error) {
      shouldContinue = false;
    }
  }

  // Step 5: Verify overview and complete order
  if (shouldContinue) {
    try {
      await overviewPage.assertOnOverviewPage();
      const total = await overviewPage.asyncGetTotal();
      expect(total).toBeGreaterThan(0);
      await overviewPage.finishOrder();
      await completePage.assertOrderComplete();
    } catch (error) {
      shouldContinue = false;
    }
  }

  // Step 6: Return to products
  if (shouldContinue) {
    try {
